export type HomeRegionNotice =
  | { kind: 'unavailable'; country: string }
  | { kind: 'supported' }
  | { kind: 'unknown' };

export const resolveHomeRegionNotice = (
  country: string | null | undefined,
  supportedCountryNames: readonly string[],
): HomeRegionNotice => {
  const normalizedCountry = country?.trim() ?? '';

  if (!normalizedCountry) {
    return { kind: 'unknown' };
  }

  if (supportedCountryNames.includes(normalizedCountry)) {
    return { kind: 'supported' };
  }

  return { kind: 'unavailable', country: normalizedCountry };
};

