import {resolveHomeRegionNotice} from '../src/screens/home/home-screen/home-screen.utils';

const supportedCountries = [
  'Hong Kong',
  'China',
  'Singapore',
  'Philippines',
  'Thailand',
];

describe('resolveHomeRegionNotice', () => {
  test('treats a GPS country inside the shared whitelist as supported', () => {
    expect(resolveHomeRegionNotice('Singapore', supportedCountries)).toEqual({
      kind: 'supported',
    });
    expect(resolveHomeRegionNotice('  Thailand  ', supportedCountries)).toEqual({
      kind: 'supported',
    });
  });

  test('asks the home screen to show the unavailable notice for a GPS country outside the whitelist', () => {
    expect(resolveHomeRegionNotice('France', supportedCountries)).toEqual({
      kind: 'unavailable',
      country: 'France',
    });
  });

  test('does not invent a country when GPS reverse geocoding has no country yet', () => {
    expect(resolveHomeRegionNotice(undefined, supportedCountries)).toEqual({
      kind: 'unknown',
    });
    expect(resolveHomeRegionNotice('   ', supportedCountries)).toEqual({
      kind: 'unknown',
    });
    expect(resolveHomeRegionNotice(null, supportedCountries)).toEqual({
      kind: 'unknown',
    });
  });
});
